import heapq

def match(orders):
    trades = []
    buy_heap = []  # (-price, arrival, id)
    sell_heap = []  # (price, arrival, id)
    book = {}  # id -> dict with side, price, qty, arrival, active
    seq = 0

    def add_order(order_id, side, price, qty, arrival):
        book[order_id] = {'side': side, 'price': price, 'qty': qty, 'arrival': arrival, 'active': True}
        if side == 'buy':
            heapq.heappush(buy_heap, (-price, arrival, order_id))
        else:
            heapq.heappush(sell_heap, (price, arrival, order_id))

    def pop_best(heap):
        while heap:
            item = heap[0]
            oid = item[2]
            o = book.get(oid)
            if o is None or not o['active'] or o['qty'] <= 0:
                heapq.heappop(heap)
                continue
            return oid
        return None

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            o = book.get(oid)
            if o and o['active'] and o['qty'] > 0:
                o['active'] = False
            continue

        seq += 1
        arrival = seq

        if typ == 'limit':
            _, oid, side, price, qty = order
        elif typ == 'ioc':
            _, oid, side, price, qty = order
        elif typ == 'market':
            _, oid, side, qty = order
            price = None
        else:
            continue

        remaining = qty
        opp_heap = sell_heap if side == 'buy' else buy_heap

        while remaining > 0:
            best_oid = pop_best(opp_heap)
            if best_oid is None:
                break
            best = book[best_oid]
            if typ != 'market':
                if side == 'buy' and best['price'] > price:
                    break
                if side == 'sell' and best['price'] < price:
                    break

            trade_qty = min(remaining, best['qty'])
            trade_price = best['price']
            if side == 'buy':
                trades.append([oid, best_oid, trade_price, trade_qty])
            else:
                trades.append([best_oid, oid, trade_price, trade_qty])

            remaining -= trade_qty
            best['qty'] -= trade_qty

            if best['qty'] == 0:
                best['active'] = False
                # remove from heap since it's exhausted
                heapq.heappop(opp_heap)

        if typ == 'limit' and remaining > 0:
            add_order(oid, side, price, remaining, arrival)
        # for market/ioc, discard remainder; do not add to book

    return trades

